import { useEffect, useState } from "react";
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { eventMoney, eventRequest } from "../../services/eventApi";
import "./EventRevenue.css";
export default function EventRevenue({initial}){const [range,setRange]=useState("monthly"),[data,setData]=useState(initial||{chart:[]}),[loading,setLoading]=useState(false);useEffect(()=>{setLoading(true);eventRequest(`/vendor/events/revenue?range=${range}`).then(setData).finally(()=>setLoading(false))},[range]);const cards=[["Total Revenue",data.totalRevenue],["Platform Commission",data.platformCommission],["Vendor Earning",data.vendorEarning],["Pending Settlement",data.pendingSettlement]];return <section><header className="er-title"><div><small>FINANCIAL PERFORMANCE</small><h1>Event Revenue</h1><p>Live earnings calculated from successful event bookings.</p></div><div>{["daily","weekly","monthly","yearly"].map(x=><button className={range===x?"active":""} onClick={()=>setRange(x)} key={x}>{x}</button>)}</div></header><section className="er-cards">{cards.map(([l,v])=><article key={l}><small>{l}</small><h2>{eventMoney(v)}</h2><span>{range} view</span></article>)}</section><article className="ed-panel"><header><div><small>LIVE REVENUE CHART</small><h3>{range[0].toUpperCase()+range.slice(1)} revenue</h3></div>{loading&&<b>Updating…</b>}</header><div className="er-chart"><ResponsiveContainer><BarChart data={data.chart||[]}><CartesianGrid vertical={false} stroke="#e7eeea"/><XAxis dataKey="label" axisLine={false} tickLine={false}/><YAxis tickFormatter={v=>`₹${Math.round(v/1000)}k`} axisLine={false} tickLine={false}/><Tooltip formatter={v=>eventMoney(v)}/><Bar dataKey="revenue" fill="#087f5b" radius={[7,7,0,0]}/></BarChart></ResponsiveContainer></div></article></section>}
